          "ባዶ አንቴና ለመሆን መጀመሪያ ፍላጎቶቻችንን በሙሉ ማጥፋት አለብን።",
          "አምስቱን የስሜት ህዋሳቶቻችንን ለማጉላት ልዩ አካላዊ መሳሪያዎች ያስፈልጉናል።",
          "መንፈሳዊውን ድግግሞሽ መያዝ የሚቻለው ከብዙ ዓመታት ብቸኛ ማሰላሰል በኋላ ብቻ ነው።"
