        correct: 0,
        rationale: "መንፈሳዊው ዓለም የመስጠት ባሕርይ ነው። እኛ ልንገነዘበው የምንችለው በውስጣችን ተዛማጅ ድግግሞሽ – ለሌሎች የመስጠት ዓላማ – ስንፈጥር ብቻ ነው።"
